package agent

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
	"google.golang.org/protobuf/types/known/timestamppb"

	antv1 "anttrader/gen/proto/ant/v1"
)

// MemoryStore manages the three-layer memory system (ADR-0025 §4).
// Layer 1: domain_knowledge (platform-managed, shared)
// Layer 2: user_strategy_templates (user-saved preferences)
// Layer 3: agent_experience (auto-generated by retrospect Agent)
type MemoryStore struct {
	pool *pgxpool.Pool
}

// NewMemoryStore creates a memory store backed by the given connection pool.
func NewMemoryStore(pool *pgxpool.Pool) *MemoryStore {
	return &MemoryStore{pool: pool}
}

// SessionMemory is the aggregated memory context injected into LLM prompts at session start.
type SessionMemory struct {
	DomainKnowledge []string
	UserTemplates   []string
	Experiences     []string
}

// LoadSessionMemory loads all three memory layers for a user, filtered by scope (ADR-0025 §4.3).
func (m *MemoryStore) LoadSessionMemory(ctx context.Context, userID uuid.UUID, symbol, timeframe string) (*SessionMemory, error) {
	mem := &SessionMemory{}

	dk, err := m.loadDomainKnowledge(ctx, symbol, timeframe)
	if err == nil {
		mem.DomainKnowledge = dk
	}

	ut, err := m.loadUserTemplates(ctx, userID, symbol, timeframe)
	if err == nil {
		mem.UserTemplates = ut
	}

	exp, err := m.loadRecentExperiences(ctx, userID, 20)
	if err == nil {
		mem.Experiences = exp
	}

	return mem, nil
}

// InjectIntoPrompt writes session memory into a prompt builder (ADR-0025 §4.3).
func (mem *SessionMemory) InjectIntoPrompt(sb *strings.Builder) {
	if len(mem.DomainKnowledge) > 0 {
		sb.WriteString("\n## Domain Knowledge\n")
		for _, dk := range mem.DomainKnowledge {
			sb.WriteString("- ")
			sb.WriteString(dk)
			sb.WriteString("\n")
		}
	}

	if len(mem.UserTemplates) > 0 {
		sb.WriteString("\n## User Preferences\n")
		for _, ut := range mem.UserTemplates {
			sb.WriteString("- ")
			sb.WriteString(ut)
			sb.WriteString("\n")
		}
	}

	if len(mem.Experiences) > 0 {
		sb.WriteString("\n## Past Experiences\n")
		for _, exp := range mem.Experiences {
			sb.WriteString("- ")
			sb.WriteString(exp)
			sb.WriteString("\n")
		}
	}
}

// loadDomainKnowledge loads active domain knowledge entries matching the given scope.
func (m *MemoryStore) loadDomainKnowledge(ctx context.Context, symbol, timeframe string) ([]string, error) {
	rows, err := m.pool.Query(ctx,
		`SELECT content FROM domain_knowledge
		 WHERE status = 'active'
		 ORDER BY created_at DESC LIMIT 20`)
	if err != nil {
		return nil, fmt.Errorf("load domain knowledge: %w", err)
	}
	defer rows.Close()

	var result []string
	for rows.Next() {
		var content string
		if err := rows.Scan(&content); err != nil {
			continue
		}
		result = append(result, content)
	}
	return result, nil
}

// loadUserTemplates loads user-saved strategy templates matching the given scope.
func (m *MemoryStore) loadUserTemplates(ctx context.Context, userID uuid.UUID, symbol, timeframe string) ([]string, error) {
	rows, err := m.pool.Query(ctx,
		`SELECT name, content FROM user_strategy_templates
		 WHERE user_id = $1
		 ORDER BY updated_at DESC LIMIT 10`,
		userID)
	if err != nil {
		return nil, fmt.Errorf("load user templates: %w", err)
	}
	defer rows.Close()

	var result []string
	for rows.Next() {
		var name, content string
		if err := rows.Scan(&name, &content); err != nil {
			continue
		}
		result = append(result, fmt.Sprintf("[%s] %s", name, content))
	}
	return result, nil
}

// loadRecentExperiences loads recent agent experiences for a user.
func (m *MemoryStore) loadRecentExperiences(ctx context.Context, userID uuid.UUID, limit int) ([]string, error) {
	rows, err := m.pool.Query(ctx,
		`SELECT content FROM agent_experience
		 WHERE user_id = $1
		 ORDER BY created_at DESC LIMIT $2`,
		userID, limit)
	if err != nil {
		return nil, fmt.Errorf("load experiences: %w", err)
	}
	defer rows.Close()

	var result []string
	for rows.Next() {
		var content string
		if err := rows.Scan(&content); err != nil {
			continue
		}
		result = append(result, content)
	}
	return result, nil
}

// StoreExperience inserts an agent experience entry (ADR-0025 §6.2).
func (m *MemoryStore) StoreExperience(ctx context.Context, userID uuid.UUID, category, content, fingerprint string, indicators []string, conditionStructure string) (string, error) {
	id := uuid.New()
	_, err := m.pool.Exec(ctx,
		`INSERT INTO agent_experience (id, user_id, category, content, fingerprint, indicators, condition_structure)
		 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		id, userID, category, content, fingerprint, indicators, conditionStructure)
	if err != nil {
		return "", fmt.Errorf("store experience: %w", err)
	}
	return id.String(), nil
}

// SearchExperiences searches agent experiences by content similarity (ILIKE fallback for now).
// pgvector embedding can be added later — current implementation uses text search.
func (m *MemoryStore) SearchExperiences(ctx context.Context, userID uuid.UUID, query, category string, limit int) ([]*antv1.ExperienceEntry, error) {
	if limit <= 0 {
		limit = 10
	}

	rows, err := m.pool.Query(ctx,
		`SELECT id, category, content, fingerprint, created_at
		 FROM agent_experience
		 WHERE user_id = $1 AND ($2 = '' OR category = $2)
		 AND ($3 = '' OR content ILIKE '%' || $3 || '%')
		 ORDER BY created_at DESC LIMIT $4`,
		userID, category, query, limit)
	if err != nil {
		return nil, fmt.Errorf("search experiences: %w", err)
	}
	defer rows.Close()

	var entries []*antv1.ExperienceEntry
	for rows.Next() {
		var id, cat, content, fp string
		var createdAt time.Time
		if err := rows.Scan(&id, &cat, &content, &fp, &createdAt); err != nil {
			continue
		}
		entries = append(entries, &antv1.ExperienceEntry{
			Id:        id,
			Category:  cat,
			Content:   content,
			MatchType: "text",
			CreatedAt: timestamppb.New(createdAt),
		})
	}
	return entries, nil
}

// SaveUserTemplate saves or updates a user strategy template.
func (m *MemoryStore) SaveUserTemplate(ctx context.Context, userID uuid.UUID, name, content string, scopeJSON string) error {
	_, err := m.pool.Exec(ctx,
		`INSERT INTO user_strategy_templates (user_id, name, content, scope)
		 VALUES ($1, $2, $3, $4::jsonb)
		 ON CONFLICT (user_id, name) DO UPDATE SET content = $3, scope = $4::jsonb, updated_at = NOW()`,
		userID, name, content, scopeJSON)
	if err != nil {
		return fmt.Errorf("save user template: %w", err)
	}
	return nil
}

// ListUserTemplates lists all user strategy templates.
func (m *MemoryStore) ListUserTemplates(ctx context.Context, userID uuid.UUID) ([]*antv1.UserTemplateEntry, error) {
	rows, err := m.pool.Query(ctx,
		`SELECT id, name, content, created_at, updated_at
		 FROM user_strategy_templates
		 WHERE user_id = $1
		 ORDER BY updated_at DESC`,
		userID)
	if err != nil {
		return nil, fmt.Errorf("list user templates: %w", err)
	}
	defer rows.Close()

	var entries []*antv1.UserTemplateEntry
	for rows.Next() {
		var id, name, content string
		var createdAt, updatedAt time.Time
		if err := rows.Scan(&id, &name, &content, &createdAt, &updatedAt); err != nil {
			continue
		}
		entries = append(entries, &antv1.UserTemplateEntry{
			Id:        id,
			Name:      name,
			Content:   content,
			CreatedAt: createdAt.Unix(),
			UpdatedAt: updatedAt.Unix(),
		})
	}
	return entries, nil
}

// DeleteUserTemplate deletes a user strategy template by ID.
func (m *MemoryStore) DeleteUserTemplate(ctx context.Context, userID uuid.UUID, templateID string) error {
	_, err := m.pool.Exec(ctx,
		`DELETE FROM user_strategy_templates WHERE id = $1 AND user_id = $2`,
		templateID, userID)
	if err != nil {
		return fmt.Errorf("delete user template: %w", err)
	}
	return nil
}

// ListAgentExperiences lists all agent experiences for a user (for /memory page).
func (m *MemoryStore) ListAgentExperiences(ctx context.Context, userID uuid.UUID) ([]*antv1.ExperienceEntry, error) {
	return m.SearchExperiences(ctx, userID, "", "", 100)
}

// DeleteAgentExperience deletes an agent experience by ID.
func (m *MemoryStore) DeleteAgentExperience(ctx context.Context, userID uuid.UUID, experienceID string) error {
	_, err := m.pool.Exec(ctx,
		`DELETE FROM agent_experience WHERE id = $1 AND user_id = $2`,
		experienceID, userID)
	if err != nil {
		return fmt.Errorf("delete agent experience: %w", err)
	}
	return nil
}
